updated_app_tsx = """import React, { useState, useEffect } from 'react';
import dotenv from 'dotenv';

dotenv.config();

interface PullRequest {
  id: number;
  title: string;
  html_url: string;
}

interface Repo {
  name: string;
}

const App: React.FC = () => {
  const [repos, setRepos] = useState<Repo[]>([]);
  const [selectedRepo, setSelectedRepo] = useState<string>('');
  const [pullRequests, setPullRequests] = useState<PullRequest[]>([]);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchRepos();
  }, []);

  useEffect(() => {
    if (selectedRepo) {
      fetchPullRequests(selectedRepo);
    }
  }, [selectedRepo]);

  const fetchRepos = async () => {
    try {
      const response = await fetch('https://api.github.com/orgs/OpenDevin/repos', {
        headers: {
          Authorization: `token ${process.env.GITHUB_TOKEN || ''}`,
        },
      });
      if (!response.ok) {
        throw new Error('Failed to fetch repositories');
      }
      const data = await response.json();
      setRepos(data);
    } catch (error) {
      console.error('Error fetching repos:', error);
      setError('Failed to fetch repositories. Please try again later.');
    }
  };

  const fetchPullRequests = async (repo: string) => {
    try {
      const response = await fetch(`https://api.github.com/repos/OpenDevin/${repo}/pulls`, {
        headers: {
          Authorization: `token ${process.env.GITHUB_TOKEN || ''}`,
        },
      });
      if (!response.ok) {
        throw new Error('Failed to fetch pull requests');
      }
      const data = await response.json();
      setPullRequests(data);
    } catch (error) {
      console.error('Error fetching pull requests:', error);
      setError('Failed to fetch pull requests. Please try again later.');
    }
  };

  return (
    <div style={{ fontFamily: 'Arial, sans-serif', maxWidth: '800px', margin: '0 auto', padding: '20px' }}>
      <h1 style={{ color: '#333' }}>PR Viewer</h1>
      {error && <p style={{ color: 'red' }}>{error}</p>}
      <select
        value={selectedRepo}
        onChange={(e) => setSelectedRepo(e.target.value)}
        style={{ padding: '5px', marginBottom: '20px' }}
      >
        <option value="">Select a repository</option>
        {repos.map((repo) => (
          <option key={repo.name} value={repo.name}>
            {repo.name}
          </option>
        ))}
      </select>
      <h2 style={{ color: '#444' }}>Pull Requests for {selectedRepo}</h2>
      {pullRequests.length === 0 ? (
        <p>No open pull requests found.</p>
      ) : (
        <ul style={{ listStyleType: 'none', padding: 0 }}>
          {pullRequests.map((pr) => (
            <li key={pr.id} style={{ marginBottom: '10px' }}>
              <a
                href={pr.html_url}
                target="_blank"
                rel="noopener noreferrer"
                style={{ color: '#0366d6', textDecoration: 'none' }}
              >
                {pr.title}
              </a>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default App;
"""

